    static final class NibView extends View{final MainActivity a;final String tool;NibView(MainActivity a,String tool){super(a);this.a=a;this.tool=tool;}protected void onDraw(Canvas c){c.save();c.translate(getWidth()/2f,getHeight()*.12f);float k=getHeight()/53f;c.scale(k,k);Paint p=new Paint(3);boolean eraser=tool.equals("eraser"),pencil=tool.equals("pencil"),marker=tool.equals("marker"),tape=tool.equals("tape");int body=eraser?0xffb2b6ba:pencil?0xffd1a37a:0xff32363b;p.setShader(new LinearGradient(-7,0,8,0,new int[]{0xff07090b,body,0xff727981,body,0xff07090b},null,Shader.TileMode.CLAMP));c.drawRoundRect(new RectF(-6,13,6,53),2,2,p);p.setShader(null);if(eraser){p.setColor(0xffe3a0a5);c.drawRoundRect(new RectF(-6,0,6,16),3,3,p);p.setColor(0xffd8dbe0);c.drawRect(-6,13,6,19,p);}else if(tape){p.setColor(0xffd49bdc);c.drawRect(-7,1,7,11,p);p.setColor(0xff3a3942);c.drawRect(-7,10,7,17,p);}else if(marker){p.setColor(0xffefd45d);c.drawRect(-5,1,5,13,p);p.setColor(0xffc3a01e);c.drawRect(-5,20,5,23,p);}else{Path tip=new Path();tip.moveTo(0,-1);tip.lineTo(-5,14);tip.lineTo(5,14);tip.close();p.setColor(pencil?0xffd9b999:tool.equals("fountain")?0xffc2c9d0:tool.equals("laser")?0xfff24962:0xff30333a);c.drawPath(tip,p);if(tool.equals("fountain")){p.setColor(0xff4b5159);p.setStrokeWidth(.6f);c.drawLine(0,1,0,11,p);c.drawCircle(0,9,1,p);}if(tool.equals("rainbow")){p.setShader(new LinearGradient(-6,22,6,22,new int[]{0xffd15a89,0xffdfbf55,0xff6abd99,0xff6789de},null,Shader.TileMode.CLAMP));c.drawRect(-6,19,6,23,p);p.setShader(null);}}c.restore();}}
